-- Seed generated from public/chapters/index.json. Idempotent.
-- The chapter bodies and images are uploaded separately to the 'chapters' bucket.

insert into public.chapters (
  slug, number, volume, title, summary, concepts, headings, figures,
  unreferenced_images, word_count, reading_minutes
)
select
  c->>'slug', (c->>'number')::int, (c->>'volume')::int, c->>'title', c->>'summary',
  array(select jsonb_array_elements_text(coalesce(c->'concepts', '[]'::jsonb))),
  coalesce(c->'headings', '[]'::jsonb), coalesce(c->'figures', '[]'::jsonb),
  array(select jsonb_array_elements_text(coalesce(c->'unreferencedImages', '[]'::jsonb))),
  (c->>'wordCount')::int, (c->>'readingMinutes')::int
